{{-- Farm performance (income vs spending, financial and production position). Needs $e = DashboardController::executiveSummary(). --}}
@php
    $cashMax = max(1, $e['monthly']->max(fn ($month) => max($month['income'], $month['spending'])));
    $spendMax = max(1, $e['spendingByArea']->max('amount') ?? 1);
    // UGX shortened for the chart labels: 12.4M, 850K.
    $short = fn ($v) => $v >= 1000000 ? rtrim(rtrim(number_format($v / 1000000, 1), '0'), '.').'M' : ($v >= 1000 ? round($v / 1000).'K' : number_format($v));
    $hasCashData = $e['monthly']->contains(fn ($month) => $month['income'] > 0 || $month['spending'] > 0);
@endphp
